import{_ as o,o as d,c as r,ag as n}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"神贴配方解剖学 —— 为什么这帮帖子能活十年","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/shengtie-formula.md","filePath":"topics/tianya/shengtie-formula.md"}'),a={name:"topics/tianya/shengtie-formula.md"};function s(e,t,u,l,i,h){return d(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="神贴配方解剖学-——-为什么这帮帖子能活十年" tabindex="-1">神贴配方解剖学 —— 为什么这帮帖子能活十年 <a class="header-anchor" href="#神贴配方解剖学-——-为什么这帮帖子能活十年" aria-label="Permalink to &quot;神贴配方解剖学 —— 为什么这帮帖子能活十年&quot;">​</a></h1><blockquote><p>整理日期：2026-11-06 · 材料：<code>notes/</code> 05—10 卷总览 + 01—04 卷交叉观察 本文是<strong>元层笔记</strong>：不复述任何帖子内容，只拆&quot;它们为什么成立&quot;。</p></blockquote><blockquote><p>关键词：天涯神贴, 神贴配方, 职业+灵异, 亲历型叙事人, 信任状, 悬置优于解释, 知识密度, 杠杆爆仓, 骗子自白, 反诈, 钩子前置, 流量生意, 叙事识别</p></blockquote><hr><h2 id="一、先看问题" tabindex="-1">一、先看问题 <a class="header-anchor" href="#一、先看问题" aria-label="Permalink to &quot;一、先看问题&quot;">​</a></h2><p>天涯每天产生海量帖子，99.9% 死了。活下来被反复考古的这批，<strong>没有一个是靠&quot;信息量&quot;活的</strong>——它们共用一套可拆解的信任装置。拆开这套装置有三个用处：读懂旧帖、识破今天的同类、以及反过来用于自己写东西。</p><hr><h2 id="二、五种配方" tabindex="-1">二、五种配方 <a class="header-anchor" href="#二、五种配方" aria-label="Permalink to &quot;二、五种配方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>配方</th><th>结构件</th><th>代表（卷）</th><th>活的理由</th><th>独有的失效条件</th></tr></thead><tbody><tr><td>1</td><td><strong>利益分析推演</strong></td><td>政策文本 → 拆利益方 → 推演政策打折与执行偏差 → 给时间表</td><td>kkndme、flp713、曼因斯坦（01/03）</td><td>决策者选项集有限，<strong>从利益出发的推演容错高</strong></td><td>把&quot;政府绝不允许跌&quot;当公理；政策目标一换即全线失效</td></tr><tr><td>2</td><td><strong>职业 + 灵异</strong></td><td>真实职业细节（信任状）+ 悬案/怪谈（糖衣）+ 悬置结尾（钩子）</td><td>天津刑警奇闻录、殡葬业者、091 气象所、DNA 鉴定师（07/08）</td><td>读者对&quot;编的&quot;极敏感，<strong>硬细节让鬼可信</strong>；哪怕不信鬼也愿为职业干货留下</td><td>细节是查来的而非经手的；完本感言一露馅全盘崩</td></tr><tr><td>3</td><td><strong>杠杆忏悔录</strong></td><td>暴富 → 加杠杆 → 爆仓数字 → 复盘点 → 劝诫</td><td>南侠1987（两次强平）、赌坛老千自述（05）</td><td>亏损比盈利可信；<strong>具体数字是道德资产</strong></td><td>作者自己也说明白：赢的前提被系统性剥夺，故事不能复制</td></tr><tr><td>4</td><td><strong>内部人揭黑</strong></td><td>自曝身份 → 列可验证造假手法 → 上升到宏观结论</td><td>招商主管自白、中国式骗局大全、国有银行基层经营（03/06）</td><td>手法具体到可当场验证 → 反诈价值永久有效</td><td>身份无法核实（详见下方&quot;滑坡&quot;）</td></tr><tr><td>5</td><td><strong>公开课/系统兜售</strong></td><td>拆体系 → 留作业 → 五级进阶 → 甚至没有爽点</td><td>慧商学院、万里依然、职业如何规划（05/06）</td><td>认真到笨拙＝最强的反流量信号</td><td>传播注定失败；被误当&quot;速成&quot;反而害人</td></tr></tbody></table><p><strong>配方 4 与 2 的边界</strong>：反诈（06 卷）与伪纪实（08 卷）用的是同一手——&quot;内部人 + 细节&quot;。区别只在<strong>细节能否被独立验证</strong>。检测器两个：<strong>利益归谁、证据可否独立验证</strong>（06 卷原话，2010 年适用，今天更适用）。</p><hr><h2 id="三、五个共用装置" tabindex="-1">三、五个共用装置 <a class="header-anchor" href="#三、五个共用装置" aria-label="Permalink to &quot;三、五个共用装置&quot;">​</a></h2><p>所有配方都在用这几件公共零件（07/08 卷总览的提炼）：</p><table tabindex="0"><thead><tr><th>装置</th><th>做法</th><th>为什么有效</th></tr></thead><tbody><tr><td><strong>1. 钩子前置</strong></td><td>楔子/序曲先给一个强场景：华佗焚书、怪尸上火车、犯人点名见记者</td><td>决定点击的那三秒</td></tr><tr><td><strong>2. 短怪谈 → 长主线</strong></td><td>先用一堆本地短故事建信任，再进贯穿全书的主线</td><td>沉没成本 + 习惯性追更</td></tr><tr><td><strong>3. 神秘机构/传承体系</strong></td><td>给怪事一个&quot;建制&quot;（民调局、五大贼王世家、御灵蒋家）</td><td>让怪事<strong>可被管理、可被继承</strong>，可无限续更</td></tr><tr><td><strong>4. 知识密度即护城河</strong></td><td>中医方剂、相术、风水、春典黑话、DNA 检测、司法程序、银行科目</td><td>硬知识让&quot;编的&quot;读起来像&quot;真的&quot;</td></tr><tr><td><strong>5. 悬置优于解释</strong></td><td>从不把话说死：&quot;冥冥中指引着我们，那就不得而知了&quot;</td><td><strong>半信半疑是可持续更新的钩子</strong>——144 靠它写了三个月，168 靠&quot;顶一下&quot;养了七年</td></tr><tr><td><strong>6. 人性兜底</strong></td><td>再邪的门，最后收束都在情（为亡妻收魂、母女养老院重逢）</td><td>把猎奇升格为共情，才有人愿意转发</td></tr></tbody></table><p><strong>装置的真相（08 卷的原话最有价值）：</strong> 纯写实的两个帖子（126 殡葬、181 检察官）也能红，说明&quot;灵异其实只是糖衣——真正立住帖子的，是<strong>行业细节、时代记忆与人的命运</strong>&quot;。1976 武汉的竹床阵、1959 江西的饥荒、1985 研究所的分房，才是天涯鬼话区留给后人的真正遗产。</p><blockquote><p>⭐ <strong>可迁移结论：糖衣会过时，糖衣底下的东西不会。</strong> 灵异＝2010 年的糖衣；今天换成了 AI、加密货币、副业躺赚。判断一个内容是不是长久货，看它扒掉糖衣后还剩什么。</p></blockquote><hr><h2 id="四、滥用滑坡-信任状衰减阶梯" tabindex="-1">四、滥用滑坡（信任状衰减阶梯） <a class="header-anchor" href="#四、滥用滑坡-信任状衰减阶梯" aria-label="Permalink to &quot;四、滥用滑坡（信任状衰减阶梯）&quot;">​</a></h2><p>同一套配方，按&quot;经手程度&quot;逐级衰减：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>手上真经手的</span></span>
<span class="line"><span>  ① 真警察写悬案（155）        ← 细节有物理痕迹（湿鞋印、&quot;连检察院那关都到不了&quot;、收音机报时）</span></span>
<span class="line"><span>  ② 亲历口吻写自己事（144）    ← 一边自嘲&quot;恐惧多半是自己吓自己&quot;，一边留一张说不清的纸人</span></span>
<span class="line"><span>  ③ 拿&quot;职业&quot;当小说皮（110/188/141/128）← 完本感言露馅</span></span>
<span class="line"><span>  ④ 蘸着职业术语东拼西凑（128 帖下立刻有人回&quot;应该是故事……真实生活中哪有这样的&quot;）</span></span>
<span class="line"><span>手上没经手的</span></span></code></pre></div><p><strong>这张阶梯就是识别器</strong>：不看它写得多像，只看<strong>细节是查来的还是经手的</strong>。经手的细节有冗余、有无聊的部分、有当时的错；查来的细节特别&quot;整齐&quot;，只服务于情节需要。</p><p><strong>推荐链接的检验（05 卷）</strong>：晒收益、开收费贴、喊财富自由者，<strong>其商业模式本身就是向粉丝收&quot;水子&quot;</strong>。听人荐股前先看他靠什么赚钱——这条同时适用于 02 卷卖课建群的房产博主。</p><hr><h2 id="五、今天在哪见到同一个配方" tabindex="-1">五、今天在哪见到同一个配方 <a class="header-anchor" href="#五、今天在哪见到同一个配方" aria-label="Permalink to &quot;五、今天在哪见到同一个配方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配方</th><th>天涯形态（2005—2020）</th><th>今天的对应物</th></tr></thead><tbody><tr><td>利益分析推演</td><td>kkndme、flp713 长帖</td><td>财经自媒体&quot;体制内视角&quot;、宏观博主</td></tr><tr><td>职业+灵异</td><td>刑警/殡葬/考古/气象所</td><td>知乎&quot;我在 X 行业&quot;系列、B 站 UP 主职业向、小红书&quot;行业内幕&quot;</td></tr><tr><td>杠杆忏悔录</td><td>南侠1987、赌坛老千</td><td>爆仓实录、币圈归零帖、雪球实盘复盘</td></tr><tr><td>内部人揭黑</td><td>招商主管自白、银行基层</td><td>反诈博主、行业离职爆料、供应链揭秘</td></tr><tr><td>公开课型</td><td>慧商学院、万里依然</td><td>系统课、训练营、开源教程</td></tr></tbody></table><p><strong>两个不变的判据</strong>（跨二十年都成立）：</p><ol><li><strong>利益归谁 + 证据能否独立验证</strong>（06 卷：骗局恒久远，套路永流传——先取信后收网，你的贪念就是他的杠杆）</li><li><strong>口吻越全知，越接近流量生意</strong>（02 卷：警惕一切&quot;准确率 100%&quot;的作者）</li></ol><hr><h2 id="六、反用途-拿来写自己的东西" tabindex="-1">六、反用途：拿来写自己的东西 <a class="header-anchor" href="#六、反用途-拿来写自己的东西" aria-label="Permalink to &quot;六、反用途：拿来写自己的东西&quot;">​</a></h2><p>这套装置反转过来就是<strong>写作检查表</strong>：</p><ul><li>[ ] <strong>钩子</strong>：标题/前三句有没有一个具体场景？（不是&quot;谈谈 X&quot;）</li><li>[ ] <strong>信任状</strong>：细节是经手的还是查来的？经手的细节请保留无聊的部分</li><li>[ ] <strong>知识密度</strong>：有没有一段&quot;只有真做过的人才知道&quot;的硬内容？</li><li>[ ] <strong>悬置</strong>：该说不知道的地方，说了没有？（不是所有问题都要收口）</li><li>[ ] <strong>兜底</strong>：落到人身上了吗？</li><li>[ ] <strong>利益声明</strong>：读者能不能一眼看出&quot;你靠什么赚钱&quot;？藏起来的就是可疑的</li></ul><blockquote><p>与 <code>ai-brain/</code> 的连接：这套表对<strong>写知识库文档同样有效</strong>——本库的落盘纪律（保留原始内容、区分事实与诠释、标&quot;未核实&quot;）本质上是把配方 1（利益分析）与配方 4（可否独立验证）制度化。</p></blockquote><hr><h2 id="七、与库内主题的接口" tabindex="-1">七、与库内主题的接口 <a class="header-anchor" href="#七、与库内主题的接口" aria-label="Permalink to &quot;七、与库内主题的接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关联</th><th>连接点</th></tr></thead><tbody><tr><td><code>tianya/index.md</code></td><td>十卷地图与六件工具</td></tr><tr><td><code>tianya/prediction-ledger.md</code></td><td>配方 1 的<strong>成绩单</strong>——推演型帖子的检验结果</td></tr><tr><td><code>psychology/</code></td><td>&quot;半信半疑是可持续更新的钩子&quot;＝注意力心理；损失厌恶（05 卷&quot;牛市拿不住、熊市装死&quot;）</td></tr><tr><td><code>source-verification</code>（skill）/ <code>science-news/</code></td><td>同一套检测器：&quot;看谁发的、能不能独立验证、失真在哪一层&quot;</td></tr><tr><td><code>philosophy/</code></td><td>&quot;糖衣会过时、底下不会&quot;＝区分现象与机制</td></tr><tr><td><code>investment-methods/</code></td><td>&quot;他靠什么赚钱&quot;＝利益结构与激励相容</td></tr></tbody></table><hr><p><em>核心原则：<strong>一个帖子能活十年，靠的不是它说了什么，而是它让读者相信&quot;这人真的在那儿&quot;。糖衣（灵异/AI/暴富）年年换，糖衣底下的东西——行业细节、时代记忆、人的命运——不换。</strong></em></p>`,37)])])}const p=o(a,[["render",s]]);export{q as __pageData,p as default};
